head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pSTYPE = "";
scwin.secjGrpId  = "";
scwin.fr_MktId = $c.session.getUserInfo("market");  // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.

let fr_SearchTyp;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 초기화함수
        scwin.init();

        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92009_SW.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {

};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    let arrPar = new Array();
    /***************************************
    opener에  fn_GetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 업종조회후  최초 지정 코드값이 없는 상태
    opener에  fn_SetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 선택한 코드값과 코드명칭을 지정하지 않는다.
     ***************************************/
    // let parentWin = frame.Provider("../");
    scwin.fn_GetPar = $c.win.getParent().fn_GetPar;
    scwin.fn_SetPar = $c.win.getParent().fn_SetPar;

    if (scwin.fn_GetPar !== undefined) {
        scwin.fn_GetPar(arrPar);
        strSch          = ((arrPar.length >= 1) && (arrPar[0] !== undefined) ? arrPar[0] : "");
        if (scwin.fr_SecuGrpId === undefined) {
            scwin.fr_SecuGrpId = ((arrPar.length >= 3) && (arrPar[2] !== undefined) ? arrPar[2] : "");
        }
        if ((arrPar.length >= 4) && (arrPar[3] !== undefined)) {
            scwin.fr_MktId = arrPar[3];
        }
    }
    if (scwin.fr_MktId !== "9") { // 전체
        grd_list.setColumnVisible("spotIsuTrdMktTpCd", true);
    }
    ibx_comAbbrv.focus();
    scwin.secjGrpId =  $c.data.getParameter("SECJ_GRP_ID");

    if(scwin.secjGrpId   === "SW" || scwin.secjGrpId  === "SR"){
        textbox_1.setValue("* 담당자와 담당팀이 없는 회사는 상장예정인 회사입니다.");
    } else{
        textbox_1.setValue("");
    }

    scwin.pSTYPE = $c.data.getParameter("STYPE");
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ibx_comAbbrv_onkeydown
 * @description ibx_comAbbrv 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ibx_comAbbrv_onkeydown = async function(e) {
    try {
        if (event.keyCode === 13) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92009_SW.ibx_comAbbrv_onkeydown" });
    }
};

/**
 * @method
 * @name grd_list_oncelldblclick
 * @description 부모창 값 리턴
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_list_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        let arrPar = new Array();

        // if (scwin.fn_SetPar !== undefined) {
        //     debugger
            arrPar[0] = {
                ISUR_CD: dlt_corpChrgSwRes.getCellData(rowIndex, "isurCd"),
                COM_NM: dlt_corpChrgSwRes.getCellData(rowIndex, "comAbbrv"),
                SPOT_ISU_TRD_MKT_TP_CD: dlt_corpChrgSwRes.getCellData(rowIndex, "spotIsuTrdMktTpCd"),
                ACNTCLS_MM: dlt_corpChrgSwRes.getCellData(rowIndex, "acntclsNm"),
                SECUGRP_ID: dlt_corpChrgSwRes.getCellData(rowIndex, "secugrpId"), // fr_SecuGrpId값과 실제 발행기관의 증권그룹이 안맞는 경우가 있어서 증권그룹id를 넘김
                SECT_TP_CD: dlt_corpChrgSwRes.getCellData(rowIndex, "sectTpCd"), // EMP_NM: dts.NameString(dts.RowPosition, "EMP_NM"),
                DBCLICKYN: "Y"
            };
        // }

        await $c.win.closePopup(arrPar[0]);

    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92009_SW.grd_list_oncelldblclick" });
    }
};

/**
 * @method
 * @name img_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_Search_onclick = async function (e) {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92009_SW.img_Search_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    dma_searchReq.set("secugrpId",scwin.secjGrpId);
    dma_searchReq.set("comAbbrv",ibx_comAbbrv.getValue());
    dma_searchReq.set("mktTpCd",scwin.fr_MktId);
    dma_searchReq.set("typeCd", scwin.pSTYPE);

    const sbmOptions = {
        id : "sbm_issuance",
        method: "get",
        ref: "dma_searchReq",
        action : "/api/listing/common/pop/issur/select-list-corp-chrg-sw",
        target : "dlt_corpChrgSwRes=body",
        isProcessMsg : true
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success) {
        txb_TotCnt.setValue(dlt_corpChrgSwRes.getRowCount())
    }

};

///////// 5. 일반/업무 함수 영역 /////////
