/**
 * @method
 * @name chageCdNm
 * @description 시장구분 명
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @returns {*}
 * @hidden N
 */
scwin.chageCdNm = function (data, formattedData, rowIndex, columnIndex) {

    if(columnIndex === 5) {
        const vSpotIsuTrdMktTpCd = dlt_corpChrgSwRes.getCellData(rowIndex, "spotIsuTrdMktTpCd")

        if(vSpotIsuTrdMktTpCd === "1") {
            data =  '유가';
        } else if(vSpotIsuTrdMktTpCd === "2") {
            data =  '코스닥';
        } else if(vSpotIsuTrdMktTpCd === "6") {
            data =  '코넥스';
        } else {
            data =  '기타';
        }
    }

    return data ;
};
